    cpu.pc += 1;
    cpu.cycle(8);
    cpu.set_hl(crate::defs::CHANNEL_MUSIC_ADDRESS as u16);
    cpu.pc += 3;
    cpu.cycle(12);
    let lhs = cpu.hl();
